import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { 
  LineChart, Line, BarChart, Bar, PieChart, Pie, Cell, 
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';

function AdminDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [users, setUsers] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [services, setServices] = useState([]);
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalProviders: 0,
    totalDrivers: 0,
    totalCustomers: 0,
    totalBookings: 0,
    completedBookings: 0,
    pendingBookings: 0,
    totalRevenue: 0,
    platformCommission: 0,
    monthlyGrowth: 12.5
  });
  const [loading, setLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState(null);
  const [showUserModal, setShowUserModal] = useState(false);
  const [filterRole, setFilterRole] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [dateRange, setDateRange] = useState('week');
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(5);

  const token = localStorage.getItem('token');

  // Sample notifications
  const notifications = [
    { id: 1, type: 'new_user', title: 'New User Registered', message: 'John Doe joined as Customer', time: '5 min ago', read: false, icon: '👤' },
    { id: 2, type: 'new_provider', title: 'Provider Application', message: 'Mike Auto Repair applied for verification', time: '1 hour ago', read: false, icon: '🔧' },
    { id: 3, type: 'new_booking', title: 'New Booking', message: 'Oil Change booked by Sarah', time: '2 hours ago', read: false, icon: '📅' },
    { id: 4, type: 'payout', title: 'Payout Request', message: 'Provider requested $500 payout', time: '5 hours ago', read: true, icon: '💰' }
  ];

  // Chart data
  const weeklyBookings = [
    { day: 'Mon', bookings: 12, revenue: 480 },
    { day: 'Tue', bookings: 15, revenue: 600 },
    { day: 'Wed', bookings: 18, revenue: 720 },
    { day: 'Thu', bookings: 14, revenue: 560 },
    { day: 'Fri', bookings: 22, revenue: 880 },
    { day: 'Sat', bookings: 25, revenue: 1000 },
    { day: 'Sun', bookings: 20, revenue: 800 }
  ];

  const userDistribution = [
    { name: 'Customers', value: stats.totalCustomers, color: '#3b82f6' },
    { name: 'Providers', value: stats.totalProviders, color: '#10b981' },
    { name: 'Drivers', value: stats.totalDrivers, color: '#f59e0b' },
    { name: 'Admins', value: 1, color: '#8b5cf6' }
  ];

  const monthlyRevenue = [
    { month: 'Jan', revenue: 12500 },
    { month: 'Feb', revenue: 15200 },
    { month: 'Mar', revenue: 18400 },
    { month: 'Apr', revenue: 16800 },
    { month: 'May', revenue: 22100 },
    { month: 'Jun', revenue: 25400 }
  ];

  useEffect(() => {
    fetchAllData();
    const interval = setInterval(fetchAllData, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      // Fetch users
      const usersRes = await fetch('http://localhost:5000/api/admin/users', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const usersData = await usersRes.json();
      if (usersData.success) {
        setUsers(usersData.users);
        updateStats(usersData.users);
      }

      // Fetch bookings
      const bookingsRes = await fetch('http://localhost:5000/api/admin/bookings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const bookingsData = await bookingsRes.json();
      if (bookingsData.success) setBookings(bookingsData.bookings);

      // Fetch services
      const servicesRes = await fetch('http://localhost:5000/api/admin/services', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const servicesData = await servicesRes.json();
      if (servicesData.success) setServices(servicesData.services);

    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const updateStats = (usersList) => {
    const customers = usersList.filter(u => u.role === 'customer').length;
    const providers = usersList.filter(u => u.role === 'provider').length;
    const drivers = usersList.filter(u => u.role === 'driver').length;

    setStats(prev => ({
      ...prev,
      totalUsers: usersList.length,
      totalCustomers: customers,
      totalProviders: providers,
      totalDrivers: drivers,
      totalBookings: bookings.length,
      completedBookings: bookings.filter(b => b.status === 'completed').length,
      pendingBookings: bookings.filter(b => b.status === 'pending').length,
      totalRevenue: 45200,
      platformCommission: 6780
    }));
  };

  const updateUserStatus = async (userId, isActive) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isActive })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`User ${isActive ? 'activated' : 'suspended'}`);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to update user');
    }
  };

  const verifyProvider = async (userId, isVerified) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isVerified })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Provider ${isVerified ? 'verified' : 'unverified'}`);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to verify provider');
    }
  };

  const toggleServiceStatus = async (serviceId, isActive) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/services/${serviceId}/status`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isActive: !isActive })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Service ${!isActive ? 'activated' : 'hidden'}`);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to update service');
    }
  };

  const getRoleBadge = (role) => {
    const config = {
      customer: { bg: '#d1fae5', color: '#065f46', icon: '👤' },
      provider: { bg: '#e0e7ff', color: '#4338ca', icon: '🔧' },
      driver: { bg: '#fef3c7', color: '#92400e', icon: '🚗' },
      admin: { bg: '#f3e8ff', color: '#7c3aed', icon: '👑' }
    };
    const c = config[role] || { bg: '#f3f4f6', color: '#6b7280', icon: '❓' };
    return <span style={{ backgroundColor: c.bg, color: c.color, padding: '4px 10px', borderRadius: '20px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '5px' }}>{c.icon} {role}</span>;
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      completed: '#8b5cf6',
      cancelled: '#ef4444'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 10px', borderRadius: '20px', fontSize: '11px', display: 'inline-block' };
  };

  // Filter users based on role and search
  const filteredUsers = users.filter(user => {
    const matchesRole = filterRole === 'all' || user.role === filterRole;
    const matchesSearch = searchTerm === '' || 
      user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.businessName?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesRole && matchesSearch;
  });

  const pendingProviders = users.filter(u => u.role === 'provider' && !u.isVerified);
  const pendingDrivers = users.filter(u => u.role === 'driver' && !u.isVerified);
  const recentBookings = bookings.slice(0, 10);

  return (
    <div style={styles.dashboard}>
      <ToastContainer position="top-right" />

      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>👑</span>
          <div>
            <h1 style={styles.logoText}>Car Care Connect - Admin</h1>
            <div style={styles.headerSubtitle}>
              Platform Management Dashboard
            </div>
          </div>
        </div>

        <div style={styles.headerRight}>
          {/* Notification Bell */}
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>
            🔔
            {unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}
          </div>

          <div style={styles.userInfo}>
            <img src={`https://ui-avatars.com/api/?background=8b5cf6&color=fff&name=${user?.firstName}`} alt="avatar" style={styles.avatar} />
            <div>
              <div style={styles.userName}>{user?.firstName} {user?.lastName}</div>
              <div style={styles.userEmail}>Super Admin</div>
            </div>
            <button onClick={onLogout} style={styles.logoutButton}>🚪</button>
          </div>
        </div>
      </div>

      {/* Notification Dropdown */}
      {showNotifications && (
        <div style={styles.notificationDropdown}>
          <div style={styles.notificationHeader}>
            <h3>🔔 Notifications</h3>
            <button style={styles.markAllRead}>Mark all read</button>
          </div>
          {notifications.map(notif => (
            <div key={notif.id} style={{ ...styles.notificationItem, opacity: notif.read ? 0.6 : 1 }}>
              <span style={styles.notificationIconSmall}>{notif.icon}</span>
              <div style={styles.notificationContent}>
                <div style={styles.notificationTitle}>{notif.title}</div>
                <div style={styles.notificationMessage}>{notif.message}</div>
                <div style={styles.notificationTime}>{notif.time}</div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>👥</div>
          <div style={styles.statInfo}>
            <h3>Total Users</h3>
            <p style={styles.statNumber}>{stats.totalUsers}</p>
            <span style={styles.statTrend}>+{stats.monthlyGrowth}%</span>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>🔧</div>
          <div style={styles.statInfo}>
            <h3>Providers</h3>
            <p style={styles.statNumber}>{stats.totalProviders}</p>
            <span style={styles.pendingBadge}>{pendingProviders.length} pending</span>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>🚗</div>
          <div style={styles.statInfo}>
            <h3>Drivers</h3>
            <p style={styles.statNumber}>{stats.totalDrivers}</p>
            <span style={styles.pendingBadge}>{pendingDrivers.length} pending</span>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>📅</div>
          <div style={styles.statInfo}>
            <h3>Bookings</h3>
            <p style={styles.statNumber}>{stats.totalBookings}</p>
            <span>{stats.completedBookings} completed</span>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>💰</div>
          <div style={styles.statInfo}>
            <h3>Revenue</h3>
            <p style={styles.statNumber}>${stats.totalRevenue.toLocaleString()}</p>
            <span>+15% vs last month</span>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>⭐</div>
          <div style={styles.statInfo}>
            <h3>Platform Rating</h3>
            <p style={styles.statNumber}>4.8</p>
            <span>From 1,234 reviews</span>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div style={styles.quickActions}>
        <button style={styles.quickActionBtn} onClick={() => setActiveTab('users')}>👥 Manage Users</button>
        <button style={styles.quickActionBtn} onClick={() => setActiveTab('providers')}>🔧 Verify Providers</button>
        <button style={styles.quickActionBtn} onClick={() => setActiveTab('services')}>🛠️ Moderate Services</button>
        <button style={styles.quickActionBtn} onClick={() => setActiveTab('bookings')}>📅 View Bookings</button>
        <button style={styles.quickActionBtn} onClick={() => setActiveTab('analytics')}>📊 Analytics</button>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'users' ? styles.activeTab : {})}} onClick={() => setActiveTab('users')}>👥 Users ({stats.totalUsers})</button>
        <button style={{...styles.tab, ...(activeTab === 'providers' ? styles.activeTab : {})}} onClick={() => setActiveTab('providers')}>🔧 Providers ({stats.totalProviders})</button>
        <button style={{...styles.tab, ...(activeTab === 'drivers' ? styles.activeTab : {})}} onClick={() => setActiveTab('drivers')}>🚗 Drivers ({stats.totalDrivers})</button>
        <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings ({stats.totalBookings})</button>
        <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => setActiveTab('services')}>🛠️ Services</button>
        <button style={{...styles.tab, ...(activeTab === 'analytics' ? styles.activeTab : {})}} onClick={() => setActiveTab('analytics')}>📈 Analytics</button>
        <button style={{...styles.tab, ...(activeTab === 'settings' ? styles.activeTab : {})}} onClick={() => setActiveTab('settings')}>⚙️ Settings</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading platform data...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div>
                <div style={styles.twoColumn}>
                  {/* Left Column - Charts */}
                  <div>
                    <div style={styles.card}>
                      <h3>📊 Weekly Bookings & Revenue</h3>
                      <ResponsiveContainer width="100%" height={300}>
                        <LineChart data={weeklyBookings}>
                          <CartesianGrid strokeDasharray="3 3" />
                          <XAxis dataKey="day" />
                          <YAxis yAxisId="left" />
                          <YAxis yAxisId="right" orientation="right" />
                          <Tooltip />
                          <Legend />
                          <Line yAxisId="left" type="monotone" dataKey="bookings" stroke="#3b82f6" name="Bookings" />
                          <Line yAxisId="right" type="monotone" dataKey="revenue" stroke="#10b981" name="Revenue ($)" />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>

                    <div style={styles.card}>
                      <h3>👥 User Distribution</h3>
                      <ResponsiveContainer width="100%" height={250}>
                        <PieChart>
                          <Pie data={userDistribution} cx="50%" cy="50%" labelLine={false} label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`} outerRadius={80} fill="#8884d8" dataKey="value">
                            {userDistribution.map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={entry.color} />
                            ))}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  {/* Right Column - Pending Items */}
                  <div>
                    <div style={styles.card}>
                      <h3>⏳ Pending Verifications</h3>
                      <div style={styles.pendingList}>
                        <div style={styles.pendingItem}>
                          <span>🔧 Provider Applications</span>
                          <span style={styles.pendingCount}>{pendingProviders.length}</span>
                          <button style={styles.reviewBtn} onClick={() => setActiveTab('providers')}>Review</button>
                        </div>
                        <div style={styles.pendingItem}>
                          <span>🚗 Driver Applications</span>
                          <span style={styles.pendingCount}>{pendingDrivers.length}</span>
                          <button style={styles.reviewBtn} onClick={() => setActiveTab('drivers')}>Review</button>
                        </div>
                      </div>
                    </div>

                    <div style={styles.card}>
                      <h3>📋 Recent Activity</h3>
                      {recentBookings.slice(0, 5).map(booking => (
                        <div key={booking._id} style={styles.activityItem}>
                          <span>📅 {booking.serviceName}</span>
                          <span>{booking.customerId?.firstName}</span>
                          <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                        </div>
                      ))}
                    </div>

                    <div style={styles.card}>
                      <h3>💰 Finance Summary</h3>
                      <div style={styles.financeItem}>
                        <span>Total Revenue:</span>
                        <strong>${stats.totalRevenue.toLocaleString()}</strong>
                      </div>
                      <div style={styles.financeItem}>
                        <span>Platform Commission (15%):</span>
                        <strong>${stats.platformCommission.toLocaleString()}</strong>
                      </div>
                      <div style={styles.financeItem}>
                        <span>Provider Payouts:</span>
                        <strong>${(stats.totalRevenue - stats.platformCommission).toLocaleString()}</strong>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Users Tab */}
            {activeTab === 'users' && (
              <div>
                <div style={styles.tableHeader}>
                  <h2>👥 User Management</h2>
                  <div style={styles.tableFilters}>
                    <select style={styles.filterSelect} value={filterRole} onChange={(e) => setFilterRole(e.target.value)}>
                      <option value="all">All Roles</option>
                      <option value="customer">Customers</option>
                      <option value="provider">Providers</option>
                      <option value="driver">Drivers</option>
                      <option value="admin">Admins</option>
                    </select>
                    <input style={styles.searchInput} type="text" placeholder="Search users..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                  </div>
                </div>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Actions</th></tr>
                    </thead>
                    <tbody>
                      {filteredUsers.map(u => (
                        <tr key={u._id}>
                          <td><strong>{u.firstName} {u.lastName}</strong>{u.businessName && <div style={styles.businessName}>{u.businessName}</div>}</td>
                          <td>{u.email}</td>
                          <td>{getRoleBadge(u.role)}</td>
                          <td><span style={{ color: u.isActive ? '#10b981' : '#ef4444' }}>{u.isActive ? 'Active' : 'Suspended'}</span></td>
                          <td>{new Date(u.createdAt).toLocaleDateString()}</td>
                          <td>
                            <button style={styles.actionBtn} onClick={() => updateUserStatus(u._id, !u.isActive)}>
                              {u.isActive ? 'Suspend' : 'Activate'}
                            </button>
                            {u.role === 'provider' && !u.isVerified && (
                              <button style={{...styles.actionBtn, backgroundColor: '#8b5cf6', marginLeft: '5px'}} onClick={() => verifyProvider(u._id, true)}>Verify</button>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Providers Tab */}
            {activeTab === 'providers' && (
              <div>
                <h2>🔧 Provider Management</h2>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>Business Name</th><th>Owner</th><th>Email</th><th>Status</th><th>Joined</th><th>Actions</th></tr>
                    </thead>
                    <tbody>
                      {users.filter(u => u.role === 'provider').map(u => (
                        <tr key={u._id}>
                          <td><strong>{u.businessName || u.firstName}</strong></td>
                          <td>{u.firstName} {u.lastName}</td>
                          <td>{u.email}</td>
                          <td><span style={{ color: u.isVerified ? '#10b981' : '#f59e0b' }}>{u.isVerified ? 'Verified' : 'Pending'}</span></td>
                          <td>{new Date(u.createdAt).toLocaleDateString()}</td>
                          <td>
                            {!u.isVerified && (
                              <button style={{...styles.actionBtn, backgroundColor: '#10b981'}} onClick={() => verifyProvider(u._id, true)}>✓ Verify</button>
                            )}
                            <button style={{...styles.actionBtn, backgroundColor: '#ef4444', marginLeft: '5px'}} onClick={() => updateUserStatus(u._id, false)}>Suspend</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Drivers Tab */}
            {activeTab === 'drivers' && (
              <div>
                <h2>🚗 Driver Management</h2>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>Name</th><th>Email</th><th>License</th><th>Vehicle</th><th>Status</th><th>Actions</th></tr>
                    </thead>
                    <tbody>
                      {users.filter(u => u.role === 'driver').map(u => (
                        <tr key={u._id}>
                          <td>{u.firstName} {u.lastName}</td>
                          <td>{u.email}</td>
                          <td>{u.driversLicense || 'N/A'}</td>
                          <td>{u.vehicleModel || 'N/A'}</td>
                          <td><span style={{ color: u.isVerified ? '#10b981' : '#f59e0b' }}>{u.isVerified ? 'Verified' : 'Pending'}</span></td>
                          <td>
                            {!u.isVerified && (
                              <button style={{...styles.actionBtn, backgroundColor: '#10b981'}} onClick={() => verifyProvider(u._id, true)}>✓ Verify</button>
                            )}
                            <button style={{...styles.actionBtn, backgroundColor: '#ef4444', marginLeft: '5px'}} onClick={() => updateUserStatus(u._id, false)}>Suspend</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Bookings Tab */}
            {activeTab === 'bookings' && (
              <div>
                <h2>📅 All Bookings ({bookings.length})</h2>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>Service</th><th>Customer</th><th>Provider</th><th>Date</th><th>Amount</th><th>Status</th></tr>
                    </thead>
                    <tbody>
                      {bookings.map(b => (
                        <tr key={b._id}>
                          <td>{b.serviceName}</td>
                          <td>{b.customerId?.firstName} {b.customerId?.lastName}</td>
                          <td>{b.providerId?.businessName || b.providerId?.firstName}</td>
                          <td>{new Date(b.bookingDate).toLocaleDateString()}</td>
                          <td>${b.totalAmount}</td>
                          <td><span style={getStatusBadge(b.status)}>{b.status}</span></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Services Tab */}
            {activeTab === 'services' && (
              <div>
                <h2>🛠️ All Services</h2>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>Name</th><th>Provider</th><th>Category</th><th>Price</th><th>Bookings</th><th>Status</th><th>Actions</th></tr>
                    </thead>
                    <tbody>
                      {services.map(s => (
                        <tr key={s._id}>
                          <td>{s.name}</td>
                          <td>{s.providerId?.businessName || s.providerId?.firstName}</td>
                          <td>{s.category}</td>
                          <td>${s.price}</td>
                          <td>{s.totalBookings || 0}</td>
                          <td><span style={{ color: s.isActive ? '#10b981' : '#ef4444' }}>{s.isActive ? 'Active' : 'Hidden'}</span></td>
                          <td>
                            <button style={{...styles.actionBtn, backgroundColor: s.isActive ? '#ef4444' : '#10b981'}} onClick={() => toggleServiceStatus(s._id, s.isActive)}>
                              {s.isActive ? 'Hide' : 'Show'}
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Analytics Tab */}
            {activeTab === 'analytics' && (
              <div>
                <h2>📈 Platform Analytics</h2>
                <div style={styles.card}>
                  <h3>Monthly Revenue Trend</h3>
                  <ResponsiveContainer width="100%" height={350}>
                    <BarChart data={monthlyRevenue}>
                      <CartesianGrid strokeDasharray="3 3" />
                      <XAxis dataKey="month" />
                      <YAxis />
                      <Tooltip />
                      <Legend />
                      <Bar dataKey="revenue" fill="#8b5cf6" name="Revenue ($)" />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
                <div style={styles.statsGrid}>
                  <div style={styles.statCard}>
                    <h3>📈 Growth Rate</h3>
                    <p style={styles.statNumber}>+{stats.monthlyGrowth}%</p>
                  </div>
                  <div style={styles.statCard}>
                    <h3>🔄 Retention Rate</h3>
                    <p style={styles.statNumber}>78%</p>
                  </div>
                  <div style={styles.statCard}>
                    <h3>⏱️ Avg Response</h3>
                    <p style={styles.statNumber}>2.5 min</p>
                  </div>
                  <div style={styles.statCard}>
                    <h3>⭐ Avg Rating</h3>
                    <p style={styles.statNumber}>4.8/5</p>
                  </div>
                </div>
              </div>
            )}

            {/* Settings Tab */}
            {activeTab === 'settings' && (
              <div style={styles.settingsContainer}>
                <h2>⚙️ Platform Settings</h2>
                <div style={styles.settingsSection}>
                  <h3>🏢 General Settings</h3>
                  <div style={styles.settingItem}>
                    <label>Platform Name</label>
                    <input type="text" value="Car Care Connect" style={styles.input} />
                  </div>
                  <div style={styles.settingItem}>
                    <label>Commission Rate</label>
                    <input type="number" value="15" style={styles.input} /> %
                  </div>
                  <div style={styles.settingItem}>
                    <label>Contact Email</label>
                    <input type="email" value="support@carcareconnect.com" style={styles.input} />
                  </div>
                </div>
                <div style={styles.settingsSection}>
                  <h3>🔔 Notification Settings</h3>
                  <label style={styles.checkboxLabel}><input type="checkbox" defaultChecked /> Email Notifications</label>
                  <label style={styles.checkboxLabel}><input type="checkbox" defaultChecked /> Push Notifications</label>
                  <label style={styles.checkboxLabel}><input type="checkbox" /> SMS Notifications</label>
                </div>
                <button style={styles.saveBtn}>Save Settings</button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

