  statIcon: { fontSize: '32px' },
  statInfo: { flex: 1 },
  statNumber: { fontSize: '24px', fontWeight: 'bold', color: '#8b5cf6', margin: '5px 0' },
  statTrend: { fontSize: '11px', color: '#10b981' },
